// ============================================================================
// src/lib/tools/radius-packet-decoder/golden-vectors.ts
// ----------------------------------------------------------------------------
// GOLDEN VECTORS for the RADIUS packet decoder.
//
// Every expected value below was derived on 2026-11-08 by a separate Python
// implementation (work/oracle.py in the build's folder), not by running this
// engine: its own hex and dump parser, its own reading of IANA's radius-types.xml,
// eap-numbers.xml and enterprise-numbers.txt, its own tables of attributes
// (RFC 2865 s5.44, RFC 2866 s5.13, RFC 2868 s4, RFC 3162 s3, RFC 2869 s5.19,
// RFC 3579 s3.3, RFC 5997 s5), and vendor sub-attribute names typed again from
// the vendors' documents. The file was written from the oracle's output by
// work/gen_vectors.py, so no expected value was typed by hand. The inputs are:
//   - every example packet of RFC 2865 section 7 (with RFC 2865 erratum 6486's
//     correction, and the published misprint, which is refused), RFC 5997
//     section 6 and RFC 5176 section 7, and the 18 attribute examples of RFC
//     6929 section 9; their decoded fields agree with the RFCs' own listings;
//   - the four course-lab packets (examples.ts);
//   - one constructed packet per rule: the text formats and their refusals, the
//     header and walk refusals (RFC 2865 s3, s5), pasted frames and TACACS+
//     headers, the packet-type tables, EAP, every RFC 8044 data type and its
//     invalid forms, the tagged tunnel attributes, the hidden attributes, the
//     vendors, the extended formats, and the API's two body forms.
// SET 2026-11-08b (p37) adds, from the same oracle extended: Huawei's Table
// 1-11 (read in a browser on 2026-11-08: the site refuses automated reads),
// with its sub-attribute note ids pinned in subNotes; the copies a Share
// results link carries (shareableCopy: which octets are zeroed, by rule, for
// every attribute, Authenticator and padding rule); and arrivals of those
// copies (redacted: true), whose zeroed fields are marked. Changed
// expectations: vsa-huawei (named, its note), vsa-huawei-types (HW-DHCP-Option
// read as DHCP options and HW-Framed-IPv6-Address's description, from rows
// 26-158 and 26-253 read in a browser at 21:05, with RFC 3046 for Option 82),
// the fifth lab packet, and new fields pinned in every reading (redacted,
// header.authenticatorRedacted, paddingRedacted).
// A vector pins the reading's fields (attributes element by element), the ids
// of its warnings and notes in order, and each attribute's invalid reason and
// notes by id; a refusal pins the id of its sentence. The page's Example (D-83)
// and its sample chips are vectors too (verifyVectors checks it).
// GOLDEN_VECTOR_SET_ID changes whenever a vector changes (the api-sync rule).
// ============================================================================

import { runLocalisable, runApi, shareableCopy, type DecodeRequest, type DecodeResult } from "./compute"; // the engine's entries
import { plainText, EngineText, type EngineTextCarrier } from "../engine-text"; // the API's projection, sentence ids
import { EXAMPLE_INPUT, SAMPLES } from "./examples"; // the page's Example and chips, checked below

/** The set id: dated, changed with any vector (scripts/check-api-sync.mjs compares it with scripts/api-sync.json). */
export const GOLDEN_VECTOR_SET_ID = "radius-packet-decoder-golden-2026-11-08b"; // 2026-11-08b: Huawei's table, the shared copy and its arrival (the first set: radius-packet-decoder-golden-2026-11-08)

/** One vector: an input (or an API body), and either the reading expected or the refusal expected. */
export interface RadiusVector {
  /** A stable id. */
  id: string;
  /** What it pins. */
  note: string;
  /** The text, for runLocalisable(). */
  input?: string;
  /** The mode, when not packet. */
  mode?: string;
  /** True for an arriving Share results copy (runLocalisable with redacted: true). */
  redacted?: boolean;
  /** Or the API body, for runApi(). */
  api?: string;
  /** The fields expected (objects compared as subsets, arrays element by element). */
  expect?: Record<string, unknown>;
  /** The warnings' sentence ids, in order. */
  warnings?: string[];
  /** The notes' sentence ids, in order. */
  notes?: string[];
  /** Each attribute's invalid reason id, or null. */
  attrInvalid?: (string | null)[];
  /** Each attribute's note ids, in order. */
  attrNotes?: string[][];
  /** The refusal's sentence id. */
  errorId?: string;
  /** Huawei sub-attributes' note ids: per attribute, per sub-attribute (null for an attribute without them). */
  subNotes?: (string[][] | null)[];
  /** Or the box for shareableCopy() (with mode), and the copy expected (null when the engine refuses the text). */
  share?: string;
  /** The copy shareableCopy() must return: text, asTyped, reason and the zeroed fields, compared exactly. */
  copy?: Record<string, unknown> | null;
}

