/**
 * Whether `actual` holds `expected`: objects as subsets, arrays of the same length element by element, anything else
 * exactly as JSON.
 * @param actual the reading's value
 * @param expected the vector's value
 * @returns true when it matches
 */
function matches(actual: unknown, expected: unknown): boolean {
  if (Array.isArray(expected)) { // a list
    if (!Array.isArray(actual) || actual.length !== expected.length) return false; // the same length
    return expected.every((e, i) => matches(actual[i], e)); // each element
  } // array
  if (expected !== null && typeof expected === "object") { // a subset object
    if (actual === null || typeof actual !== "object") return false; // nothing to compare with
    return Object.entries(expected as Record<string, unknown>).every(([k, v]) => matches((actual as Record<string, unknown>)[k], v)); // each field
  } // object
  return JSON.stringify(actual) === JSON.stringify(expected); // exact, as JSON
} // matches

/** The report verifyVectors returns. */
export interface VerifyReport {
  /** The set id. */
  setId: string;
  /** Vectors run. */
  total: number;
  /** Vectors that passed. */
  passed: number;
  /** One line per failure (empty when all pass). */
  failures: string[];
}

/** A sentence's id, or null. */
const idOf = (m: unknown): string | null => (m instanceof EngineText ? m.id : null); // the pack key under engine.*

/**
 * Run every vector, and check that the page's Example and chips are vector inputs.
 * @returns the report (failures empty when all pass)
 */
export function verifyVectors(): VerifyReport {
  const failures: string[] = []; // collected
  for (const v of RADIUS_VECTORS) { // each vector
    if (v.share !== undefined) { // a shared copy
      const c = shareableCopy({ input: v.share, mode: v.mode }); // the engine's copy
      if (JSON.stringify(c) !== JSON.stringify(v.copy ?? null)) failures.push(`${v.id}: copy ${JSON.stringify(c).slice(0, 300)}`); // exactly the oracle's
      continue; // next vector
    } // copy
    let loc: DecodeResult<EngineText> | null = null; // the localisable reading (page vectors)
    let api: DecodeResult | null = null; // the API reading (API vectors)
    try {
      if (v.api !== undefined) api = runApi(v.api); // the API body
      else loc = runLocalisable({ input: v.input ?? "", mode: v.mode, redacted: v.redacted === true } as DecodeRequest); // the page's entry (an arriving copy when redacted)
    } catch (e) {
      const id = (e as EngineTextCarrier | null)?.engineText?.id ?? `(no id: ${e instanceof Error ? e.message : String(e)})`; // the refusal's id
      if (!v.errorId) failures.push(`${v.id}: unexpected refusal ${id}`); // should have decoded
      else if (id !== v.errorId) failures.push(`${v.id}: refusal ${id}, expected ${v.errorId}`); // the wrong refusal
      continue; // next vector
    } // ran
    if (v.errorId) { failures.push(`${v.id}: expected the refusal ${v.errorId}, got a reading`); continue; } // should have refused
    const plain = api ?? (plainText(loc) as DecodeResult); // the API's shape
    if (v.expect && !matches(plain, v.expect)) failures.push(`${v.id}: fields differ: ${JSON.stringify(plain).slice(0, 300)}`); // a field moved
    if (loc) { // the sentence ids (the page's reading)
      const w = loc.warnings.map(idOf); // warning ids
      if (v.warnings && JSON.stringify(w) !== JSON.stringify(v.warnings)) failures.push(`${v.id}: warnings ${JSON.stringify(w)}, expected ${JSON.stringify(v.warnings)}`); // warnings
      const n = loc.notes.map(idOf); // note ids
      if (v.notes && JSON.stringify(n) !== JSON.stringify(v.notes)) failures.push(`${v.id}: notes ${JSON.stringify(n)}, expected ${JSON.stringify(v.notes)}`); // notes
      const inv = loc.attributes.map((a) => idOf(a.invalid)); // invalid ids
      if (v.attrInvalid && JSON.stringify(inv) !== JSON.stringify(v.attrInvalid)) failures.push(`${v.id}: invalid ${JSON.stringify(inv)}, expected ${JSON.stringify(v.attrInvalid)}`); // invalid reasons
      const an = loc.attributes.map((a) => a.notes.map(idOf)); // attribute note ids
      if (v.attrNotes && JSON.stringify(an) !== JSON.stringify(v.attrNotes)) failures.push(`${v.id}: attribute notes ${JSON.stringify(an)}, expected ${JSON.stringify(v.attrNotes)}`); // attribute notes
      if (v.subNotes) { // Huawei sub-attributes' note ids
        const sn = loc.attributes.map((a, i) => (v.subNotes?.[i] === null ? null : (a.vendor?.subs ?? []).map((s) => s.notes.map(idOf)))); // the same shape
        if (JSON.stringify(sn) !== JSON.stringify(v.subNotes)) failures.push(`${v.id}: sub-attribute notes ${JSON.stringify(sn)}, expected ${JSON.stringify(v.subNotes)}`); // sub notes
      } // sub notes
    } // ids
  } // vectors
  const inputs = new Set(RADIUS_VECTORS.map((v) => `${v.mode ?? "packet"}|${v.input ?? ""}`)); // every page input
  if (!inputs.has(`packet|${EXAMPLE_INPUT}`)) failures.push("example: the page's Example is not a vector input"); // D-83
  for (const [chip, hex, mode] of SAMPLES) if (!inputs.has(`${mode}|${hex}`)) failures.push(`chip ${chip}: not a vector input`); // every chip
  const failed = new Set(failures.map((f) => f.split(":")[0])).size; // vectors that failed
  return { setId: GOLDEN_VECTOR_SET_ID, total: RADIUS_VECTORS.length, passed: RADIUS_VECTORS.length - failed, failures }; // the report
} // verifyVectors
